begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not has_table_privilege('authenticated','public.output_fields','INSERT,UPDATE,DELETE,SELECT'),'Catalogue is server-owned and not a raw table endpoint');
select ok(not has_table_privilege('authenticated','public.output_presets','INSERT,UPDATE,DELETE,SELECT'),'Preset ownership cannot be bypassed through raw tables');
select ok(not has_table_privilege('authenticated','private.output_requests','INSERT,UPDATE,DELETE,SELECT'),'Preset retry cache is private');
select ok(not has_function_privilege('authenticated','private.output_receipt(uuid,text,uuid,jsonb)','EXECUTE'),'Raw recipient helper is private');
select ok(not has_function_privilege('anon','public.prepare_output(text,text,uuid,jsonb,text[],jsonb,uuid,uuid,integer)','EXECUTE'),'Anonymous output denied');
select ok(not has_table_privilege('carrier_security','public.financial_events','INSERT,UPDATE,DELETE') and not has_table_privilege('carrier_security','public.journal_lines','INSERT,UPDATE,DELETE'),'Customization cannot post or erase accounting');
select ok(not pg_has_role('postgres','carrier_security','SET') and not has_schema_privilege('carrier_security','private','CREATE'),'Temporary migration privileges revoked');
select ok((select bool_and(prosecdef and proconfig @> array['search_path=""']) from pg_proc where oid in('public.prepare_output(text,text,uuid,jsonb,text[],jsonb,uuid,uuid,integer)'::regprocedure,'public.save_output_preset(uuid,uuid,integer,jsonb)'::regprocedure)),'Output definers pin search paths');
select set_config('request.jwt.claims','{}',true);
set local role authenticated;
select throws_ok($$select public.get_output_catalogue('OWNER_STATEMENT','OWNER')$$,'42501','FORBIDDEN','Catalogue requires live staff');
select throws_ok($$select public.prepare_output('OWNER_STATEMENT','OWNER',gen_random_uuid(),'{"from":"2026-01-01","to":"2026-01-31"}',array['scope'])$$,'42501','FORBIDDEN','Output requires live staff');
select throws_ok($$select public.list_output_presets('OWNER_STATEMENT','OWNER')$$,'42501','FORBIDDEN','Preset listing requires live staff');
select throws_ok($$select public.save_output_preset(gen_random_uuid(),gen_random_uuid(),0,'{}')$$,'42501','FORBIDDEN','Preset creation requires live staff');
reset role;
select * from finish();
rollback;
